('MCV-Q001','A','Jak opowiedział(a)byś swoją historię zawodową komuś, kto nie zna Twojej branży?','Jak opowiedział(a)byś swoją historię zawodową komuś, kto nie zna Twojej branży?','Wychwycenie tożsamości, przewodniego motywu i języka, którym mówi użytkownik.','long_text','{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true}'::jsonb,true,ARRAY['career_facts']::text[],ARRAY['identity','career_narrative']::text[],'Wyodrębnij kolejne etapy, decyzje, motyw przewodni i deklarowane specjalizacje. Nie twórz nazw stanowisk.',ARRAY['answer_contains_relevant_detail_or_gap']::text[],ARRAY['identity','career_narrative']::text[],true,'{"id":"MCV-Q001","order":1,"section_id":"A","section_title_pl":"Tożsamość i kierunek","question_pl":"Jak opowiedział(a)byś swoją historię zawodową komuś, kto nie zna Twojej branży?","answer_type":"long_text","required":false,"input_config":{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true},"helper_text_pl":"Wychwycenie tożsamości, przewodniego motywu i języka, którym mówi użytkownik.","example_prompt_pl":"Opowiedz od pierwszej istotnej decyzji zawodowej do obecnego momentu.","ai_extraction_instruction_pl":"Wyodrębnij kolejne etapy, decyzje, motyw przewodni i deklarowane specjalizacje. Nie twórz nazw stanowisk.","conditional_followups":[{"condition":"answer_contains_relevant_detail_or_gap","question_pl":"Co zmieniło się w Twoim podejściu do pracy między początkiem kariery a dziś?","max_occurrences":1}],"career_tags":["identity","career_narrative"],"storage_visibility":"profile_internal","share_in_cv_by_default":false,"user_can_edit":true,"user_can_skip":true}'::jsonb),
('MCV-Q002','A','Co sprawia, że czujesz, że wykonujesz naprawdę dobrą pracę?','Co sprawia, że czujesz, że wykonujesz naprawdę dobrą pracę?','Uchwycenie wewnętrznej motywacji i definicji sukcesu.','long_text','{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true}'::jsonb,true,ARRAY['career_facts']::text[],ARRAY['motivation','values']::text[],'Wyodrębnij motywatory i preferowane rezultaty; nie przedstawiaj ich jako osiągnięć.',ARRAY['answer_contains_relevant_detail_or_gap']::text[],ARRAY['motivation','values']::text[],true,'{"id":"MCV-Q002","order":2,"section_id":"A","section_title_pl":"Tożsamość i kierunek","question_pl":"Co sprawia, że czujesz, że wykonujesz naprawdę dobrą pracę?","answer_type":"long_text","required":false,"input_config":{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true},"helper_text_pl":"Uchwycenie wewnętrznej motywacji i definicji sukcesu.","example_prompt_pl":"Może chodzi o widoczny efekt, uporządkowanie chaosu albo wpływ na innych.","ai_extraction_instruction_pl":"Wyodrębnij motywatory i preferowane rezultaty; nie przedstawiaj ich jako osiągnięć.","conditional_followups":[{"condition":"answer_contains_relevant_detail_or_gap","question_pl":"Podaj sytuację, w której szczególnie mocno to poczułeś(-aś).","max_occurrences":1}],"career_tags":["motivation","values"],"storage_visibility":"profile_internal","share_in_cv_by_default":false,"user_can_edit":true,"user_can_skip":true}'::jsonb),
('MCV-Q003','A','Z jakich trzech umiejętności lub cech zawodowych najchętniej chcesz być znany(-a) i dlaczego?','Z jakich trzech umiejętności lub cech zawodowych najchętniej chcesz być znany(-a) i dlaczego?','Zebranie mocnych stron wraz z historiami potwierdzającymi.','long_text','{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true}'::jsonb,true,ARRAY['career_facts']::text[],ARRAY['skills','differentiators']::text[],'Mapuj deklarację umiejętności i osobny przykład; ustaw evidence_status na claimed, dopóki nie ma dowodu.',ARRAY['answer_contains_relevant_detail_or_gap']::text[],ARRAY['skills','differentiators']::text[],true,'{"id":"MCV-Q003","order":3,"section_id":"A","section_title_pl":"Tożsamość i kierunek","question_pl":"Z jakich trzech umiejętności lub cech zawodowych najchętniej chcesz być znany(-a) i dlaczego?","answer_type":"long_text","required":false,"input_config":{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true},"helper_text_pl":"Zebranie mocnych stron wraz z historiami potwierdzającymi.","example_prompt_pl":"Do każdej cechy dopisz konkretny przykład z pracy.","ai_extraction_instruction_pl":"Mapuj deklarację umiejętności i osobny przykład; ustaw evidence_status na claimed, dopóki nie ma dowodu.","conditional_followups":[{"condition":"answer_contains_relevant_detail_or_gap","question_pl":"Co konkretnie zrobiłeś(-aś), że inni mogli tę cechę zauważyć?","max_occurrences":1}],"career_tags":["skills","differentiators"],"storage_visibility":"profile_internal","share_in_cv_by_default":false,"user_can_edit":true,"user_can_skip":true}'::jsonb),
('MCV-Q004','A','Jakie rodzaje problemów lubisz rozwiązywać, a jakich wolał(a)byś unikać?','Jakie rodzaje problemów lubisz rozwiązywać, a jakich wolał(a)byś unikać?','Zidentyfikowanie naturalnej specjalizacji i antypreferencji.','long_text','{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true}'::jsonb,true,ARRAY['career_facts']::text[],ARRAY['preferences','role_fit']::text[],'Zapisz osobno preferencje i ograniczenia; nigdy nie publikuj ich automatycznie w CV.',ARRAY['answer_contains_relevant_detail_or_gap']::text[],ARRAY['preferences','role_fit']::text[],true,'{"id":"MCV-Q004","order":4,"section_id":"A","section_title_pl":"Tożsamość i kierunek","question_pl":"Jakie rodzaje problemów lubisz rozwiązywać, a jakich wolał(a)byś unikać?","answer_type":"long_text","required":false,"input_config":{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true},"helper_text_pl":"Zidentyfikowanie naturalnej specjalizacji i antypreferencji.","example_prompt_pl":"Opisz zadania, w których tracisz poczucie czasu, oraz takie, które Cię wyczerpują.","ai_extraction_instruction_pl":"Zapisz osobno preferencje i ograniczenia; nigdy nie publikuj ich automatycznie w CV.","conditional_followups":[{"condition":"answer_contains_relevant_detail_or_gap","question_pl":"Czy możesz podać przykład takiego zadania z ostatniego roku?","max_occurrences":1}],"career_tags":["preferences","role_fit"],"storage_visibility":"profile_internal","share_in_cv_by_default":false,"user_can_edit":true,"user_can_skip":true}'::jsonb),
('MCV-Q005','B','Przejdź przez najważniejsze role w swojej karierze: co miałeś(-aś) dostarczyć w każdej z nich?','Przejdź przez najważniejsze role w swojej karierze: co miałeś(-aś) dostarczyć w każdej z nich?','Odtworzenie sensu ról bez kopiowania listy obowiązków z CV.','long_text','{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true}'::jsonb,true,ARRAY['career_facts']::text[],ARRAY['employment','responsibilities']::text[],'Powiąż cele i obowiązki z konkretnym stanowiskiem oraz datami istniejącymi w profilu. Nie zgaduj brakujących.',ARRAY['answer_contains_relevant_detail_or_gap']::text[],ARRAY['employment','responsibilities']::text[],true,'{"id":"MCV-Q005","order":5,"section_id":"B","section_title_pl":"Historia i zakres odpowiedzialności","question_pl":"Przejdź przez najważniejsze role w swojej karierze: co miałeś(-aś) dostarczyć w każdej z nich?","answer_type":"long_text","required":false,"input_config":{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true},"helper_text_pl":"Odtworzenie sensu ról bez kopiowania listy obowiązków z CV.","example_prompt_pl":"Dla każdej roli: cel, odpowiedzialność, odbiorca pracy, główny rezultat.","ai_extraction_instruction_pl":"Powiąż cele i obowiązki z konkretnym stanowiskiem oraz datami istniejącymi w profilu. Nie zgaduj brakujących.","conditional_followups":[{"condition":"answer_contains_relevant_detail_or_gap","question_pl":"Który obowiązek był faktycznie Twój, mimo że nie wynikał z nazwy stanowiska?","max_occurrences":1}],"career_tags":["employment","responsibilities"],"storage_visibility":"profile_internal","share_in_cv_by_default":false,"user_can_edit":true,"user_can_skip":true}'::jsonb),
('MCV-Q006','B','Co robiłeś(-aś) samodzielnie, a co wymagało zgody innych?','Co robiłeś(-aś) samodzielnie, a co wymagało zgody innych?','Weryfikacja autonomii i poziomu seniority.','long_text','{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true}'::jsonb,true,ARRAY['career_facts']::text[],ARRAY['ownership','seniority']::text[],'Rozróżnij accountable, responsible, consulted i informed; nie zamieniaj współpracy w zarządzanie.',ARRAY['answer_contains_relevant_detail_or_gap']::text[],ARRAY['ownership','seniority']::text[],true,'{"id":"MCV-Q006","order":6,"section_id":"B","section_title_pl":"Historia i zakres odpowiedzialności","question_pl":"Co robiłeś(-aś) samodzielnie, a co wymagało zgody innych?","answer_type":"long_text","required":false,"input_config":{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true},"helper_text_pl":"Weryfikacja autonomii i poziomu seniority.","example_prompt_pl":"Przywołaj decyzje, budżety, akceptacje lub obszary, za które odpowiadałeś(-aś).","ai_extraction_instruction_pl":"Rozróżnij accountable, responsible, consulted i informed; nie zamieniaj współpracy w zarządzanie.","conditional_followups":[{"condition":"answer_contains_relevant_detail_or_gap","question_pl":"Kto miał ostateczną odpowiedzialność za wynik?","max_occurrences":1}],"career_tags":["ownership","seniority"],"storage_visibility":"profile_internal","share_in_cv_by_default":false,"user_can_edit":true,"user_can_skip":true}'::jsonb),
('MCV-Q007','B','Kiedy i dlaczego zakres Twojej odpowiedzialności zwiększał się lub zmieniał?','Kiedy i dlaczego zakres Twojej odpowiedzialności zwiększał się lub zmieniał?','Odkrycie awansów funkcjonalnych, zaufania i rosnącej skali.','long_text','{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true}'::jsonb,true,ARRAY['career_facts']::text[],ARRAY['growth','employment']::text[],'Powiąż zmianę odpowiedzialności z rolą i okresem; nie dopisuj formalnego awansu, jeśli go nie było.',ARRAY['answer_contains_relevant_detail_or_gap']::text[],ARRAY['growth','employment']::text[],true,'{"id":"MCV-Q007","order":7,"section_id":"B","section_title_pl":"Historia i zakres odpowiedzialności","question_pl":"Kiedy i dlaczego zakres Twojej odpowiedzialności zwiększał się lub zmieniał?","answer_type":"long_text","required":false,"input_config":{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true},"helper_text_pl":"Odkrycie awansów funkcjonalnych, zaufania i rosnącej skali.","example_prompt_pl":"Napisz o nowych zadaniach, klientach, projektach lub delegowanych decyzjach.","ai_extraction_instruction_pl":"Powiąż zmianę odpowiedzialności z rolą i okresem; nie dopisuj formalnego awansu, jeśli go nie było.","conditional_followups":[{"condition":"answer_contains_relevant_detail_or_gap","question_pl":"Po czym poznałeś(-aś), że organizacja zaczęła bardziej Ci ufać?","max_occurrences":1}],"career_tags":["growth","employment"],"storage_visibility":"profile_internal","share_in_cv_by_default":false,"user_can_edit":true,"user_can_skip":true}'::jsonb),
('MCV-Q008','B','Jakie mniej oczywiste doświadczenia z pracy mogłyby być cenne w zupełnie innej branży?','Jakie mniej oczywiste doświadczenia z pracy mogłyby być cenne w zupełnie innej branży?','Ujawnienie transferowalnych umiejętności na potrzeby pivotu.','long_text','{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true}'::jsonb,true,ARRAY['career_facts']::text[],ARRAY['transferable_skills','career_pivot']::text[],'Wydobądź umiejętności transferowalne z przywołanym kontekstem; nie dopisuj znajomości nowej branży.',ARRAY['answer_contains_relevant_detail_or_gap']::text[],ARRAY['transferable_skills','career_pivot']::text[],true,'{"id":"MCV-Q008","order":8,"section_id":"B","section_title_pl":"Historia i zakres odpowiedzialności","question_pl":"Jakie mniej oczywiste doświadczenia z pracy mogłyby być cenne w zupełnie innej branży?","answer_type":"long_text","required":false,"input_config":{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true},"helper_text_pl":"Ujawnienie transferowalnych umiejętności na potrzeby pivotu.","example_prompt_pl":"Np. koordynacja przetargu, proces decyzyjny, kontakty z urzędem, automatyzacja raportów.","ai_extraction_instruction_pl":"Wydobądź umiejętności transferowalne z przywołanym kontekstem; nie dopisuj znajomości nowej branży.","conditional_followups":[{"condition":"answer_contains_relevant_detail_or_gap","question_pl":"Do jakich innych typów stanowisk ta umiejętność mogłaby się przydać?","max_occurrences":1}],"career_tags":["transferable_skills","career_pivot"],"storage_visibility":"profile_internal","share_in_cv_by_default":false,"user_can_edit":true,"user_can_skip":true}'::jsonb),
('MCV-Q009','C','Opowiedz szczegółowo o projekcie, który najlepiej pokazuje, na co Cię stać.','Opowiedz szczegółowo o projekcie, który najlepiej pokazuje, na co Cię stać.','Stworzenie flagowego case study.','long_text','{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true}'::jsonb,true,ARRAY['career_facts']::text[],ARRAY['projects','achievements']::text[],'Utwórz projekt i relacje: problem, działania, rezultat, środki, dowody; przypisz właścicielstwo działań.',ARRAY['answer_contains_relevant_detail_or_gap']::text[],ARRAY['projects','achievements']::text[],true,'{"id":"MCV-Q009","order":9,"section_id":"C","section_title_pl":"Projekty, decyzje i wpływ","question_pl":"Opowiedz szczegółowo o projekcie, który najlepiej pokazuje, na co Cię stać.","answer_type":"long_text","required":false,"input_config":{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true},"helper_text_pl":"Stworzenie flagowego case study.","example_prompt_pl":"Problem → zadanie → Twoje działania → przeszkody → efekt → czego się nauczyłeś(-aś).","ai_extraction_instruction_pl":"Utwórz projekt i relacje: problem, działania, rezultat, środki, dowody; przypisz właścicielstwo działań.","conditional_followups":[{"condition":"answer_contains_relevant_detail_or_gap","question_pl":"Co zrobiono by inaczej, gdyby Ciebie w tym projekcie nie było?","max_occurrences":1}],"career_tags":["projects","achievements"],"storage_visibility":"profile_internal","share_in_cv_by_default":false,"user_can_edit":true,"user_can_skip":true}'::jsonb),
('MCV-Q010','C','Jakie były największe skale przedsięwzięć, z którymi realnie pracowałeś(-aś)?','Jakie były największe skale przedsięwzięć, z którymi realnie pracowałeś(-aś)?','Ustalenie miar skali z poprawnym opisem osobistego udziału.','long_text','{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true}'::jsonb,true,ARRAY['career_facts']::text[],ARRAY['scope','metrics']::text[],'Zapisz liczby wraz z jednostką, walutą, okresem i relacją do roli; rozróżnij „budżet projektu” i „budżet zarządzany osobiście”.',ARRAY['answer_contains_relevant_detail_or_gap']::text[],ARRAY['scope','metrics']::text[],true,'{"id":"MCV-Q010","order":10,"section_id":"C","section_title_pl":"Projekty, decyzje i wpływ","question_pl":"Jakie były największe skale przedsięwzięć, z którymi realnie pracowałeś(-aś)?","answer_type":"long_text","required":false,"input_config":{"multiline":true,"min_length":0,"recommended_min_words":40,"max_length":5000,"allow_skip":true,"allow_voice_transcript":true},"helper_text_pl":"Ustalenie miar skali z poprawnym opisem osobistego udziału.","example_prompt_pl":"Możesz podać budżet projektu, liczbę lokalizacji, wielkość zespołu czy portfel kontraktów; doprecyzuj, czym zarządzałeś(-aś).","ai_extraction_instruction_pl":"Zapisz liczby wraz z jednostką, walutą, okresem i relacją do roli; rozróżnij „budżet projektu” i „budżet zarządzany osobiście”.","conditional_followups":[{"condition":"answer_contains_relevant_detail_or_gap","question_pl":"Czy ta liczba jest potwierdzona i czy można ją publicznie ujawnić?","max_occurrences":1}],"career_tags":["scope","metrics"],"storage_visibility":"profile_internal","share_in_cv_by_default":false,"user_can_edit":true,"user_can_skip":true}'::jsonb),
