-- Generated by npm run seed:questions from the authoritative Product Kit JSON.
-- No English translation was supplied: legacy en stores the original Polish wording.
-- Existing legacy questions/answers are retained and deactivated, never deleted.
begin;
update public.interview_questions set active=false where active=true;
on conflict(id) do update set section=excluded.section,pl=excluded.pl,en=excluded.en,why=excluded.why,answer_type=excluded.answer_type,validation=excluded.validation,optional=excluded.optional,entities=excluded.entities,competencies=excluded.competencies,extraction_instructions=excluded.extraction_instructions,follow_up_triggers=excluded.follow_up_triggers,requirement_categories=excluded.requirement_categories,active=excluded.active,metadata=excluded.metadata;
commit;
